/**************************
 * MCP Tools for Veryfront Dev Server
 **************************/
import { defineSchema, lazySchema } from "../../src/schemas/index.js";
import { getErrorCollector } from "../../src/observability/error-collector.js";
import { getLogBuffer } from "../../src/observability/log-buffer.js";
import { createFileSystem } from "../../src/platform/index.js";
import { getEnvironmentConfig } from "../../src/config/index.js";
import { advancedTools } from "./advanced-tools.js";
import { remoteFileTools } from "./remote-file-tools.js";
import { issuesMcpTools } from "../../src/issues/index.js";
import { context7Tools } from "./tools/context7-tools.js";
import { DEFAULT_MCP_PORT } from "../shared/constants.js";
const CACHE_DIRS = {
    all: [".cache/veryfront-modules", ".cache/veryfront-mdx-esm"],
    modules: [".cache/veryfront-modules"],
    mdx: [".cache/veryfront-mdx-esm"],
};
let serverStartTime = Date.now();
export function setServerStartTime(time) {
    serverStartTime = time;
}
const getGetErrorsInput = defineSchema((v) => v.object({
    type: v.enum(["compile", "runtime", "bundle", "hmr", "module"]).optional().describe("Filter by error type. Example: 'compile'. Omit to return all types."),
    file: v.string().optional().describe("Filter by file path. Example: 'app/page.tsx'. Omit to return errors from all files."),
    limit: v.number().optional().default(50).describe("Maximum number of errors to return. Defaults to 50."),
}));
const getErrorsInput = lazySchema(getGetErrorsInput);
export const vfGetErrors = {
    name: "vf_get_errors",
    title: "Get Errors",
    annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
    description: "Use this when you need to check for compilation, runtime, bundle, HMR, or module errors in the dev server. Returns error details including file path, line number, and message. Do not use for server logs. Use vf_get_logs instead.",
    inputSchema: getErrorsInput,
    execute: async (input) => {
        const errors = getErrorCollector().getAll({
            type: input.type,
            file: input.file,
        });
        if (input.limit && errors.length > input.limit)
            return errors.slice(-input.limit);
        return errors;
    },
};
const getGetLogsInput = defineSchema((v) => v.object({
    level: v.enum(["debug", "info", "warn", "error"]).optional().describe("Filter by log level. Example: 'error'. Omit to return all levels."),
    source: v.string().optional().describe("Filter by log source. Example: 'server', 'hmr', 'transform'. Omit to return all sources."),
    pattern: v.string().optional().describe("Filter by pattern (case-insensitive substring match). Example: 'timeout'."),
    limit: v.number().optional().default(100).describe("Maximum number of log entries to return. Defaults to 100."),
    since: v.number().optional().describe("Only return logs after this Unix timestamp in milliseconds."),
}));
const getLogsInput = lazySchema(getGetLogsInput);
export const vfGetLogs = {
    name: "vf_get_logs",
    title: "Get Logs",
    annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
    description: "Use this when you need to inspect server logs to understand runtime behavior or debug request handling. Returns log entries with timestamp, level, source, and message. Do not use for build/compile errors. Use vf_get_errors instead.",
    inputSchema: getLogsInput,
    execute: async (input) => {
        return getLogBuffer().query({
            level: input.level,
            source: input.source,
            pattern: input.pattern,
            limit: input.limit,
            since: input.since,
        });
    },
};
const getClearCacheInput = defineSchema((v) => v.object({
    type: v.enum(["all", "modules", "mdx"]).optional().default("all").describe("Type of cache to clear. Example: 'modules'. Defaults to 'all'."),
}));
const clearCacheInput = lazySchema(getClearCacheInput);
export const vfClearCache = {
    name: "vf_clear_cache",
    title: "Clear Cache",
    annotations: {
        readOnlyHint: false,
        destructiveHint: true,
        idempotentHint: true,
        openWorldHint: false,
    },
    description: "Use this when the dev server shows stale modules or MDX content. Returns the list of cleared cache directories. Do not use to fix code errors. Code errors require code changes.",
    inputSchema: clearCacheInput,
    execute: async (input) => {
        const fs = createFileSystem();
        const cleared = [];
        const cacheDirs = CACHE_DIRS[input.type] ?? [];
        for (const dir of cacheDirs) {
            try {
                await fs.remove(dir, { recursive: true });
                cleared.push(dir);
            }
            catch {
                // Directory doesn't exist
            }
        }
        getErrorCollector().clear();
        return { success: true, cleared };
    },
};
const getGetStatusInput = defineSchema((v) => v.object({}));
const getStatusInput = lazySchema(getGetStatusInput);
export function createVfGetStatus(env = getEnvironmentConfig()) {
    return {
        name: "vf_get_status",
        title: "Server Status",
        annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
        description: "Use this when you need a quick summary of the dev server's uptime, error counts, and warning counts. Note: always reports running=true when the MCP server is reachable. Do not use for detailed error info. Use vf_get_errors instead.",
        inputSchema: getStatusInput,
        execute: async () => {
            const errors = getErrorCollector();
            const logs = getLogBuffer();
            const counts = errors.countByType();
            const port = env.port ?? DEFAULT_MCP_PORT;
            return {
                running: true,
                url: `http://localhost:${port}`,
                port,
                errorCount: counts.compile + counts.runtime + counts.bundle,
                warningCount: logs.query({ level: "warn" }).length,
                logCount: logs.count,
                uptime: Date.now() - serverStartTime,
            };
        },
    };
}
export const vfGetStatus = createVfGetStatus();
const getClearErrorsInput = defineSchema((v) => v.object({
    file: v.string().optional().describe("Clear errors for a specific file only. Example: 'app/page.tsx'. Omit to clear all files."),
    type: v.enum(["compile", "runtime", "bundle", "hmr", "module"]).optional().describe("Clear errors of a specific type only. Example: 'compile'. Omit to clear all types."),
}));
const clearErrorsInput = lazySchema(getClearErrorsInput);
export const vfClearErrors = {
    name: "vf_clear_errors",
    title: "Clear Errors",
    annotations: {
        readOnlyHint: false,
        destructiveHint: true,
        idempotentHint: true,
        openWorldHint: false,
    },
    description: "Use this when you need to clear accumulated errors from the error collector, optionally filtering by file or type. Returns the number of cleared errors. Do not use for viewing errors. Use vf_get_errors instead.",
    inputSchema: clearErrorsInput,
    execute: async (input) => {
        const collector = getErrorCollector();
        if (input.file)
            return { cleared: collector.clearFile(input.file) };
        if (input.type)
            return { cleared: collector.clearType(input.type) };
        const cleared = collector.count;
        collector.clear();
        return { cleared };
    },
};
export const allTools = [
    ...advancedTools,
    ...remoteFileTools,
    ...issuesMcpTools,
    ...context7Tools,
    vfGetErrors,
    vfGetLogs,
    vfClearCache,
    vfGetStatus,
    vfClearErrors,
];
export function getTool(name) {
    return allTools.find((tool) => tool.name === name);
}
export function listTools() {
    return allTools.map(({ name, description }) => ({ name, description }));
}
